function UIHomeDialogueNode:Awake()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id2010)
    CfUtils.SetUISwitchImage(self.BtnChange.transform:Find("ImgIcon"), isUnlock and 1 or 2)
    ---这里节点是通过canvas group 控制显示隐藏的 不会出现 事件未被释放的情况
    self._eventHandleFun = Events.AddListener(Constants.EventNames.UIEventHomeRoleQuickTapAction, Bind(self, self.OnRoleTapAction))

    ---@type UnityEngine.Camera
    self.mCamera = URPCameraController.mainCamera
    self.newNode = self.BtnChange.transform:Find("NewMarkNode")
    local selfRectTransform = self.ImgBg:GetComponent(_RectTransform)
    self._cacheRectTrans = selfRectTransform
    self.canvasGroup = KTool.GetComponent(self.controller.gameObject, typeof(CS.UnityEngine.CanvasGroup))
    self:SetAlpha(0)
    --self._contentSizeFilter = KTool.GetComponent(self.DialogText.gameObject, typeof(ContentSizeFitter))
    UIEventProxy.Create(self.BtnChange.gameObject).onPointerClick = Bind(self, self.OnChangeCharacterButtonAction)
    self.switchRoleButton = self.controller.transform:Find("BtnTransformation")
    if self.switchRoleButton then
        local lockTrans = self.switchRoleButton:Find("ImgIcon")
        if lockTrans then
            CfUtils.SetUISwitchImage(lockTrans.gameObject, 2)
        end
        UIEventProxy.Create(self.switchRoleButton.gameObject).onPointerClick = function()
            self:OnSwitchCatAction(CatState.Role)
        end
    end
    self.switchCatButton = self.controller.transform:Find("BtnTransformation2")
    if self.switchCatButton then
        local lockTrans = self.switchCatButton:Find("ImgIcon")
        if lockTrans then
            self.lockTrans = lockTrans
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, 3)
        end
        UIEventProxy.Create(self.switchCatButton.gameObject).onPointerClick = function()
            self:OnSwitchCatAction(CatState.Cat)
        end
    end
    self.switchCoverButton = self.controller.transform:Find("BtnTransformation3")
    if self.switchCoverButton then
        local lockTrans = self.switchCoverButton:Find("ImgIcon")
        if lockTrans then
            CfUtils.SetUISwitchImage(lockTrans.gameObject, 2)
        end
        UIEventProxy.Create(self.switchCoverButton.gameObject).onPointerClick = function()
            self:OnSwitchCatAction(CatState.Cover)
        end
    end
    KTool.SetActive(self.newNode.gameObject, false)
    
    if checkNumber(self.cardId) <= 0 then
         ---@type PlayerComponent
         local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
         if playerComponent then
             local cardDojo = playerComponent:GetSignboardCardDojo()
             self.cardId = checkNumber(cardDojo.cardId)
             self.skinId = checkNumber(cardDojo.cardSkin)
             self.playerCardId = checkNumber(cardDojo.id)

             self:PlayHomeTouchVoiceByCardId(nil, true)
            
         end
     end

    ----- IdolLive3D 入口按钮
    self:_GetIdolLive3DButtonTF()
    if isNotNull(self.idolLive3DButtonTF) then             
        UIEventProxy.Create(self.idolLive3DButtonTF.gameObject).onPointerClick = function()
            self:OnClickLive3DButton()
        end
        KTool.SetActive( self.idolLive3DButtonTF.gameObject, false ) -- 按钮默认关闭的
    end 

    ---
     self:SetLockState()
end


function UIHomeDialogueNode:SetLockState(state)
    ---@type CardVo
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(self.cardId)
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id2010)
    CfUtils.SetUISwitchImage(self.BtnChange.transform:Find("ImgIcon"), isUnlock and 1 or 2)
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(self.playerCardId)
    state = state or checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))
    if state == CatState.Cat then
        if checkNumber(cardDojo.favorabilityLevel) < cardVo.mainCat then
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, 3)
        else
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, 1)
        end
        if self.switchCoverButton then
            local lockTrans = self.switchCoverButton:Find("ImgIcon")
            if lockTrans then
                CfUtils.SetUISwitchImage(lockTrans.gameObject, 2)
            end
        end
        if self.switchRoleButton then
            local lockTrans = self.switchRoleButton:Find("ImgIcon")
            if lockTrans then
                CfUtils.SetUISwitchImage(lockTrans.gameObject, 2)
            end
        end
    end
    if state == CatState.Role then
        if checkNumber(cardDojo.favorabilityLevel) < cardVo.mainCat then
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, 3)
        else
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, 2)
        end
        if self.switchCoverButton then
            local lockTrans = self.switchCoverButton:Find("ImgIcon")
            if lockTrans then
                CfUtils.SetUISwitchImage(lockTrans.gameObject, 2)
            end
        end
        if self.switchRoleButton then
            local lockTrans = self.switchRoleButton:Find("ImgIcon")
            if lockTrans then
                CfUtils.SetUISwitchImage(lockTrans.gameObject, 1)
            end
        end
    end
    if state == CatState.Cover then
        if checkNumber(cardDojo.favorabilityLevel) < cardVo.mainCat then
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, 3)
        else
            CfUtils.SetUISwitchImage(self.lockTrans.gameObject, 2)
        end
        if self.switchCoverButton then
            local lockTrans = self.switchCoverButton:Find("ImgIcon")
            if lockTrans then
                CfUtils.SetUISwitchImage(lockTrans.gameObject, 1)
            end
        end
        if self.switchRoleButton then
            local lockTrans = self.switchRoleButton:Find("ImgIcon")
            if lockTrans then
                CfUtils.SetUISwitchImage(lockTrans.gameObject, 2)
            end
        end
    end
end

function UIHomeDialogueNode:SetAlpha(alpha)
    ---@type UnityEngine.CanvasGroup
    local canvasGroup = self.canvasGroup
    if alpha > 0.5 then
        self.state = State.DialogueShow
        self:StartRefreshCo()
    else
        self.state = State.DialogueHide
    end
    GameUtils.UpdateUIShowStateByCanvasGroup(canvasGroup, self.state == State.DialogueShow)
end

function UIHomeDialogueNode:OnSwitchCatAction(cateState)
    self._showTimes = 0
    if checkNumber(self.playerCardId) <= 0 then
        return
    end
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(self.playerCardId)
    if isNull(cardDojo) then
        return
    end
    if cateState == CatState.Cat then
        ---@type CardVo
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
        if checkNumber(cardDojo.favorabilityLevel) < cardVo.mainCat then
            GameUtils.Toast(localize('好感度达到_level_级解锁', { _level_ = cardVo.mainCat }))
            return
        end
        self._catInteractionController:OnEnable()
    else
        self._catInteractionController:OnDisable()
    end
    ----当前是猫还是人
    local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))
   
    if state ~= cateState then
        state = cateState ---猫型态
        if self.skinId > 0 then
            ---@type XMainHome
            local homeEnv = UIModule.CurrentScreen.Env
            if homeEnv then
                homeEnv:ShowSignboard(cardDojo, nil, state)
            end
            self:SetLockState(cateState)
        end
    end
end


function UIHomeDialogueNode:OnEnable()
    local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))
    if state == CatState.Cat then
        self._catInteractionController:OnEnable()
    end

end

function UIHomeDialogueNode:OnDisable()
    if self._voiceId then
        CriWareUtils.StopById(self._voiceId)
        self._voiceId = nil
    end
    self._roleTouchAnimIndex = 1
    self._catInteractionController:OnDisable()
    -- if isNotNull(self._refreshCo) then
    --    cs_coroutine.stop(self._refreshCo) 
    --    self._refreshCo = nil
    -- end

end

function UIHomeDialogueNode:StartRefreshCo()
    if isNotNull(self._refreshCo) then
        return 
    end
    self._refreshCo = cs_coroutine.start(function() 
        local yield_return = cs_coroutine.yield_return
        while true do
            ---如果台词被隐藏并且猫交互是未激活状态则退出协程
            if State.DialogueHide == self.state and self._catInteractionController:IsInactive() then
                break
            end
            if self._showTimes then
                if self._showTimes >= self.voiceTime then
                    self._showTimes = nil
                    self:SetAlpha(0)
                else
                    self._showTimes = self._showTimes + intervalTime
                end
            end
            self._catInteractionController:SwitchStateByTimer(intervalTime)
            yield_return(Seconds)
            
        end
        self._refreshCo = nil
    end)
end

function UIHomeDialogueNode:StopRefreshCo()
    if isNotNull(self._refreshCo) then
        cs_coroutine.stop(self._refreshCo) 
        self._refreshCo = nil
     end
end
