function UIHomeDialogueNode:OnRoleTapAction(t)
    self._showTimes = 0
    local isChange = self.cardId ~= checkNumber(t.cardId)
    self.cardId = checkNumber(t.cardId)
    self.skinId = checkNumber(t.skinId)
    self.playerCardId = checkNumber(t.playerCardId)
    if self.cardId <= 0 then
        return
    end
    self:SetAlpha(1)
    self:SetLockState()
    local skinId = self.skinId
    local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))
    local go = nil
    ---@type CardProgressionUtils
    local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
    ---@type CardProgressionControllerRole
    local env = CardProgressionUtils.GetRoleControllerEnv()
    if state == 1 then
        go = env:GetRoleBySkinId(skinId)
        if go then
            ---@type CardVo
            local cardVo = CardConfMgr:GetInstance():GetCardByRefId(self.cardId)
            ---@type UnityEngine.Animator
            local animator = KTool.GetComponent(go, typeof(Animator))
            if cardVo and checkNumber(cardVo.rare) == Constants.RareType.SSR then
                ---special anim
                if animator then
                    local t = { lobby_01, lobby_03 }
                    local index = self._roleTouchAnimIndex
                    animator:CrossFade(t[index], DeltaTime)
                    self._roleTouchAnimIndex = index % 2 + 1
                end
            else
                if animator then
                    animator:CrossFade(lobby_01, DeltaTime)
                end
            end
        end
        self:PlayHomeTouchVoiceByCardId(go)


    elseif state == 2 then
        self._catInteractionController:SetCardId(self.cardId, skinId)
        self._catInteractionController:SwitchStateByTouch()
        if isChange then
            self:PlayHomeTouchVoiceByCardId(nil, true)
        end
    --     ---@type CatTouchController
    --     local touchController = env:GetTouchController()
    --     if touchController then
    --         if self._catTouchState == CatTouchStatus.Sit then
    --             self._interactionTime = 0
    --             if touchController:RandomAction() then
    --                 self._catTouchState = CatTouchStatus.Interaction
    --             end
    
    --         elseif self._catTouchState == CatTouchStatus.Interaction and self._interactionTime > DeepInteractionTriggerTime then
    --             self._catTouchState = CatTouchStatus.DeepInteraction
    --             touchController:EnterDeepInteraction()
    --         end
    --     end
        
    end

    ---
    self:RefreshIdolLive3DButton()    
end

---PlayHomeTouchVoiceByCardId
---播放主界面点击交互语音 （只是在人型状态播）
function UIHomeDialogueNode:PlayHomeTouchVoiceByCardId(go, ignoreVoice)
    ---@type RoleVoiceVo
    local vo = roleVoiceMgr:PlayHomeTouchVoiceByCardId(self.cardId, go, ignoreVoice, self.skinId)
    local voiceTime = ShowTime
    if vo then
        self._voiceId = vo:GetVoicecode()
        ---@type SoundVo
        local soundVo = CfUtils.GetCfVo(AutoIds.IdSetting567, "SoundVo", self._voiceId)
        voiceTime = soundVo ~= nil and soundVo.voiceTime / 1000 or ShowTime
        
    end
    ---播放当前卡牌的台词
    if vo then
        local desc = vo:GetDesk()
        if CS.Engine.I18N.I18NModule.Lang ~= "en_US" and CS.Engine.I18N.I18NModule.Lang ~= "en_UK" then
            local ChapterUtils = import('Game.Chapter.ChapterUtils')
            desc = ChapterUtils.ReplaceStr(desc, " ", utf8.char(160))
        end
        CfUtils.FillCfText(self.TxtDesc, desc)
    else
        local errorTips = string.format("卡牌<%s>未在【角色表/角色台词表】找到对应数据", tostring(self.cardId))
        if Config.DEBUG then
            CfUtils.FillCfText(self.TxtDesc, string.format("<color=#FF66FF>%s</color>", errorTips))
        else
            printError(errorTips)
        end
    end

    self.voiceTime = voiceTime
end

