function UIHomeDialogueNode:OnClickHideViewBtnAction()
    self.state = self.state == State.DialogueShow and State.DialogueHide or State.DialogueShow
    local isActive = self.state ~= State.DialogueHide
    self:RefreshUIShowState(isActive)
end

function UIHomeDialogueNode:OnChangeCharacterButtonAction()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id2010)
    if not isUnlock then
        local desc = GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id2010)
        if not string.isEmpty(desc) then
            GameUtils.Toast(desc)
        end
        return
    end
    if self.state ~= State.DialogueShow then
        return
    end
    self:SetAlpha(0)
    ---打开换人页面
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIChangeCharacterBillboard, parameters = {}}, { { id = Constants.UITypeIds.UIHomeView } })
end



function UIHomeDialogueNode:_GetIdolLive3DButtonTF()
    if isNull(self.idolLive3DButtonTF) then 
        self.idolLive3DButtonTF = self.ImgBg.transform:Find("BtnInteractive")  -- IdolLive3D 入口按钮
        self.live3DBtnGray = self.idolLive3DButtonTF:Find("ImgIcon") -- 置灰
    end 
end


-- 切换角色后, 只有配表中开启了 idolLive3D 功能的皮肤, 才能显示按钮:
function UIHomeDialogueNode:RefreshIdolLive3DButton()
    self:_GetIdolLive3DButtonTF()
    if isNull(self.idolLive3DButtonTF) then 
        return 
    end 
    --- 
    local skinId = self.skinId
    local btnTF = self.idolLive3DButtonTF
    if isNotNull(IdolLive3D_Utils.GetLive3DCardVoRow(skinId)) then -- 这个皮肤支持 深度互动
        if IdolLive3D_Utils.IsBuyThisSkinsLive3D(skinId) == false then -- 没额外购买这个皮肤的 深度互动服务
            CfUtils.MarkGray(self.live3DBtnGray.gameObject, true)
        else 
            CfUtils.MarkGray(self.live3DBtnGray.gameObject, false)
        end
        KTool.SetActive( btnTF.gameObject, true )
    else 
        KTool.SetActive( btnTF.gameObject, false ) 
    end 
end



function UIHomeDialogueNode:OnClickLive3DButton()
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    ---
    local skinId = checkInt(cardComponent:GetCardById(self.playerCardId).cardSkin)
    IdolLive3D_Loader.TryOpenScene( skinId )
end



